#include <zephyr/data/json.h>
#include <zephyr/sys/slist.h>
#include <zephyr/sys/util.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <ctype.h>

#define LOG_LEVEL CONFIG_JSON_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(json);

#define JSON_TOKEN_BUF_SIZE 128

/*
 * The JSON library uses a simple tokenizer that returns tokens from the
 * input string. The tokens are then used by the parser to build the
 * data structure.
 *
 * The tokenizer is implemented as a state machine. The state is kept in
 * the json_obj_token structure.
 *
 * The tokenizer does not allocate any memory. It only returns pointers
 * to the input string.
 */

static int json_next_token(const char *json_string, size_t json_string_len,
			   struct json_obj_token *token, size_t *offset)
{
	const char *p = json_string + *offset;
	const char *end = json_string + json_string_len;

	token->start = NULL;
	token->len = 0;

	/* Skip whitespace */
	while (p < end && isspace((unsigned char)*p)) {
		p++;
	}

	if (p == end) {
		return -ENODATA;
	}

	token->start = p;

	switch (*p) {
	case '{':
		token->type = JSON_OBJ_TOKEN_OBJECT_START;
		p++;
		break;
	case '}':
		token->type = JSON_OBJ_TOKEN_OBJECT_END;
		p++;
		break;
	case '[':
		token->type = JSON_OBJ_TOKEN_ARRAY_START;
		p++;
		break;
	case ']':
		token->type = JSON_OBJ_TOKEN_ARRAY_END;
		p++;
		break;
	case ':':
		token->type = JSON_OBJ_TOKEN_COLON;
		p++;
		break;
	case ',':
		token->type = JSON_OBJ_TOKEN_COMMA;
		p++;
		break;
	case '"':
		token->type = JSON_OBJ_TOKEN_STRING;
		p++;
		token->start = p;
		while (p < end) {
			if (*p == '"' && *(p - 1) != '\\') {
				break;
			}
			p++;
		}
		if (p == end) {
			return -EINVAL;
		}
		token->len = p - token->start;
		p++;
		break;
	case '-':
	case '0':
	case '1':
	case '2':
	case '3':
	case '4':
	case '5':
	case '6':
		case '7':
	case '8':
	case '9':
		token->type = JSON_OBJ_TOKEN_NUMBER;
		while (p < end && (isdigit((unsigned char)*p) || *p == '.' ||
					*p == '-' || *p == '+' ||
					*p == 'e' || *p == 'E')) {
			p++;
		}
		token->len = p - token->start;
		break;
	case 't':
		token->type = JSON_OBJ_TOKEN_TRUE;
		if (p + 3 < end && !strncmp(p, "true", 4)) {
			p += 4;
		} else {
			return -EINVAL;
		}
		token->len = p - token->start;
		break;
	case 'f':
		token->type = JSON_OBJ_TOKEN_FALSE;
		if (p + 4 < end && !strncmp(p, "false", 5)) {
			p += 5;
		} else {
			return -EINVAL;
		}
		token->len = p - token->start;
		break;
	case 'n':
		token->type = JSON_OBJ_TOKEN_NULL;
		if (p + 3 < end && !strncmp(p, "null", 4)) {
			p += 4;
		} else {
			return -EINVAL;
		}
		token->len = p - token->start;
		break;
	default:
		return -EINVAL;
	}

	*offset = p - json_string;

	return 0;
}

static int json_read_string(struct json_obj_token *tokens, size_t token_count,
			    const struct json_obj_descr *descr, char **str_ptr)
{
	char *str_buf = *str_ptr;
	size_t max_len = descr->string.max_len;

	if (tokens[0].type != JSON_OBJ_TOKEN_STRING) {
		return -EINVAL;
	}

	if (tokens[0].len >= max_len) {
		return -ENOSPC;
	}

	memcpy(str_buf, tokens[0].start, tokens[0].len);
	str_buf[tokens[0].len] = '\0';

	return 1;
}

static int json_read_int(struct json_obj_token *tokens, size_t token_count,
			 const struct json_obj_descr *descr, int *val)
{
	char buf[JSON_TOKEN_BUF_SIZE];

	if (tokens[0].type != JSON_OBJ_TOKEN_NUMBER) {
		return -EINVAL;
	}

	if (tokens[0].len >= sizeof(buf)) {
		return -ENOSPC;
	}

	memcpy(buf, tokens[0].start, tokens[0].len);
	buf[tokens[0].len] = '\0';

	*val = atoi(buf);

	return 1;
}

static int json_read_bool(struct json_obj_token *tokens, size_t token_count,
			  const struct json_obj_descr *descr, bool *val)
{
	if (tokens[0].type == JSON_OBJ_TOKEN_TRUE) {
		*val = true;
	} else if (tokens[0].type == JSON_OBJ_TOKEN_FALSE) {
		*val = false;
	} else {
		return -EINVAL;
	}

	return 1;
}

